using System.Collections;
using UnityEngine;
#if UNITY_EDITOR
using UnityEditor;
#endif

public class LumberPrototypeBootstrap : MonoBehaviour
{
    Transform player, axePivot, carryAnchor, sawmill; Camera cam; Animator animator;
    RuntimeAnimatorController normalController;
    bool wasMoving, wasRunning, chopping; float moveHeldTime,nextChopTime; Vector2 touchStart; bool dragging;
    int boards; TreeNode nearbyTree; GameObject carriedLog; GUIStyle hudStyle,hintStyle;
    const float WalkSpeed=2.6f,RunSpeed=4.4f,RunDelay=1.35f,ChopRange=2.15f,TreeStopDistance=1.15f,PickupRange=1.6f,SawmillRange=2.2f;

    [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)] static void AutoStart(){if(FindFirstObjectByType<LumberPrototypeBootstrap>()==null)new GameObject("Lumber Empire Demo").AddComponent<LumberPrototypeBootstrap>();}
    void Start(){foreach(var c in FindObjectsByType<Camera>(FindObjectsSortMode.None))Destroy(c.gameObject);RenderSettings.ambientLight=new Color(.72f,.76f,.68f);MakeGround();MakeLight();MakeCamera();MakePlayer();MakeForest();MakeSawmill();}
    Vector2 ReadMoveInput(){Vector2 input=new(Input.GetAxisRaw("Horizontal"),Input.GetAxisRaw("Vertical"));if(Input.touchCount>0){Touch t=Input.GetTouch(0);if(t.phase==TouchPhase.Began){touchStart=t.position;dragging=true;}if(dragging&&(t.phase==TouchPhase.Moved||t.phase==TouchPhase.Stationary)){Vector2 delta=t.position-touchStart;if(delta.magnitude>12)input=Vector2.ClampMagnitude(delta/90f,1);}if(t.phase==TouchPhase.Ended||t.phase==TouchPhase.Canceled)dragging=false;}else if(Input.GetMouseButtonDown(0)){touchStart=Input.mousePosition;dragging=true;}else if(Input.GetMouseButton(0)&&dragging){Vector2 delta=(Vector2)Input.mousePosition-touchStart;if(delta.magnitude>12)input=Vector2.ClampMagnitude(delta/90f,1);}else if(Input.GetMouseButtonUp(0))dragging=false;return input;}
    void Update(){if(player==null)return;nearbyTree=FindClosestTree();if(!chopping){Vector2 input=ReadMoveInput();Vector3 d=new(input.x,0,input.y);if(d.sqrMagnitude>1)d.Normalize();bool moving=d.sqrMagnitude>.01f;moveHeldTime=moving?moveHeldTime+Time.deltaTime:0;bool running=moving&&moveHeldTime>=RunDelay;float speed=running?RunSpeed:WalkSpeed;if(moving){Vector3 next=player.position+d*speed*Time.deltaTime;if(FindTreeNear(next,TreeStopDistance)==null)player.position=next;player.rotation=Quaternion.Slerp(player.rotation,Quaternion.LookRotation(d),12*Time.deltaTime);}if(animator!=null){if(!moving&&wasMoving)FreezeStandingPose();else if(moving&&!wasMoving)StartWalking();else if(running&&!wasRunning)StartRunning();}wasMoving=moving;wasRunning=running;}
        if(ActionPressed()){if(carriedLog!=null&&NearSawmill())DeliverLog();else if(carriedLog==null&&TryPickupLog()){}else if(nearbyTree!=null&&Time.time>=nextChopTime){StartCoroutine(ChopTree(nearbyTree));nextChopTime=Time.time+.65f;}}
        if(cam!=null){Vector3 target=player.position+new Vector3(9.5f,11,-9.5f);cam.transform.position=Vector3.Lerp(cam.transform.position,target,5*Time.deltaTime);}}
    bool ActionPressed(){if(Input.GetKeyDown(KeyCode.Space)||Input.GetKeyDown(KeyCode.E))return true;if(Input.touchCount>0){Touch t=Input.GetTouch(0);if(t.phase==TouchPhase.Ended&&(t.position-touchStart).magnitude<18)return true;}return Input.GetMouseButtonUp(0)&&((Vector2)Input.mousePosition-touchStart).magnitude<18;}
    TreeNode FindClosestTree(){TreeNode best=null;float bestD=ChopRange*ChopRange;foreach(var t in FindObjectsByType<TreeNode>(FindObjectsSortMode.None)){if(t.felled)continue;Vector3 d=t.transform.position-player.position;d.y=0;if(d.sqrMagnitude<bestD){bestD=d.sqrMagnitude;best=t;}}return best;}
    TreeNode FindTreeNear(Vector3 p,float range){float rr=range*range;foreach(var t in FindObjectsByType<TreeNode>(FindObjectsSortMode.None)){if(t.felled)continue;Vector3 d=t.transform.position-p;d.y=0;if(d.sqrMagnitude<rr)return t;}return null;}
    IEnumerator ChopTree(TreeNode tree){if(tree==null||tree.felled)yield break;chopping=true;wasMoving=false;wasRunning=false;moveHeldTime=0;Vector3 face=tree.transform.position-player.position;face.y=0;if(face.sqrMagnitude>.01f)player.rotation=Quaternion.LookRotation(face);if(animator!=null)FreezeStandingPose();yield return SwingAxe();tree.Hit();yield return ImpactFlash(tree.transform.position+Vector3.up*1.15f);if(tree.hitsLeft<=0){tree.felled=true;yield return FellTree(tree);}chopping=false;}
    IEnumerator SwingAxe(){if(axePivot==null)yield break;axePivot.gameObject.SetActive(true);yield return new WaitForSeconds(.46f);axePivot.gameObject.SetActive(false);}
    IEnumerator ImpactFlash(Vector3 p){var chip=GameObject.CreatePrimitive(PrimitiveType.Cube);chip.transform.position=p;chip.transform.localScale=new Vector3(.16f,.08f,.28f);Paint(chip,new Color(.75f,.48f,.22f));Destroy(chip.GetComponent<Collider>());Vector3 start=p,end=p+new Vector3(Random.Range(-.6f,.6f),.55f,Random.Range(-.6f,.6f));float t=0;while(t<1){t+=Time.deltaTime*5;chip.transform.position=Vector3.Lerp(start,end,t)+Vector3.up*Mathf.Sin(t*Mathf.PI)*.35f;yield return null;}Destroy(chip);}
    IEnumerator FellTree(TreeNode tree){Transform tr=tree.transform;Quaternion start=tr.rotation;Vector3 axis=Vector3.Cross(Vector3.up,(tr.position-player.position).normalized);if(axis.sqrMagnitude<.01f)axis=Vector3.right;Quaternion end=Quaternion.AngleAxis(82,axis)*start;float t=0;while(t<1){t+=Time.deltaTime*1.45f;tr.rotation=Quaternion.Slerp(start,end,Mathf.SmoothStep(0,1,t));yield return null;}Vector3 p=tr.position;yield return new WaitForSeconds(.2f);Destroy(tr.gameObject);for(int i=0;i<3;i++)MakeLog(p+new Vector3((i-1)*.65f,.25f,Random.Range(-.3f,.3f)));var stump=GameObject.CreatePrimitive(PrimitiveType.Cylinder);stump.transform.position=p+Vector3.up*.18f;stump.transform.localScale=new Vector3(.5f,.18f,.5f);Paint(stump,new Color(.48f,.28f,.12f));Destroy(stump.GetComponent<Collider>());}
    void MakeLog(Vector3 p){var log=GameObject.CreatePrimitive(PrimitiveType.Cylinder);log.name="Carryable Log";log.tag="Respawn";log.transform.position=p;log.transform.localScale=new Vector3(.24f,.62f,.24f);log.transform.rotation=Quaternion.Euler(0,0,90);Paint(log,new Color(.55f,.31f,.13f));var col=log.GetComponent<Collider>();if(col!=null)col.isTrigger=true;}
    GameObject ClosestLog(){GameObject best=null;float bd=PickupRange*PickupRange;foreach(var o in GameObject.FindGameObjectsWithTag("Respawn")){Vector3 d=o.transform.position-player.position;d.y=0;if(d.sqrMagnitude<bd){bd=d.sqrMagnitude;best=o;}}return best;}
    bool TryPickupLog(){var log=ClosestLog();if(log==null)return false;carriedLog=log;if(carryAnchor==null){var a=new GameObject("Carry Anchor");a.transform.SetParent(player,false);a.transform.localPosition=new Vector3(0,1.15f,.72f);carryAnchor=a.transform;}var c=log.GetComponent<Collider>();if(c!=null)c.enabled=false;log.transform.SetParent(carryAnchor,false);log.transform.localPosition=Vector3.zero;log.transform.localRotation=Quaternion.Euler(0,0,90);return true;}
    bool NearSawmill(){if(sawmill==null)return false;Vector3 d=sawmill.position-player.position;d.y=0;return d.sqrMagnitude<=SawmillRange*SawmillRange;}
    void DeliverLog(){Destroy(carriedLog);carriedLog=null;boards+=2;StartCoroutine(BoardPop());}
    IEnumerator BoardPop(){if(sawmill==null)yield break;for(int i=0;i<2;i++){var b=GameObject.CreatePrimitive(PrimitiveType.Cube);b.transform.position=sawmill.position+new Vector3(-1+i*.7f,1.15f,.9f);b.transform.localScale=new Vector3(.6f,.12f,.18f);Paint(b,new Color(.72f,.48f,.22f));Destroy(b.GetComponent<Collider>());Destroy(b,1.8f);}yield return null;}
    void OnGUI(){if(hudStyle==null){hudStyle=new GUIStyle(GUI.skin.box){fontSize=24,alignment=TextAnchor.MiddleCenter,fontStyle=FontStyle.Bold};hintStyle=new GUIStyle(GUI.skin.box){fontSize=19,alignment=TextAnchor.MiddleCenter,fontStyle=FontStyle.Bold};}GUI.Box(new Rect(18,18,190,52),"BOARDS  "+boards,hudStyle);string hint="";if(carriedLog!=null)hint=NearSawmill()?"TAP • DELIVER TO SAWMILL":"CARRY LOG TO SAWMILL";else if(ClosestLog()!=null)hint="TAP • PICK UP LOG";else if(nearbyTree!=null&&!nearbyTree.felled)hint=nearbyTree.hitsLeft+" HITS • CHOP";if(hint!="")GUI.Box(new Rect(Screen.width/2-175,Screen.height-82,350,52),hint,hintStyle);}
    void StartWalking(){animator.speed=1;animator.Play("Walking",0,0);animator.Update(0);}void StartRunning(){animator.speed=1;int h=Animator.StringToHash("Running");if(animator.HasState(0,h))animator.Play(h,0,0);else{animator.Play("Walking",0,0);animator.speed=1.55f;}animator.Update(0);}void FreezeStandingPose(){animator.speed=1;animator.Play("Walking",0,.08f);animator.Update(0);animator.speed=0;}
    void MakePlayer(){animator=FindFirstObjectByType<Animator>();GameObject obj=animator!=null?animator.gameObject:null;
#if UNITY_EDITOR
        if(obj==null){var prefab=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Hodaart/HodaartLowPolyCharacterCollection3/Prefabs/Character 06.prefab");if(prefab!=null)obj=Instantiate(prefab);}
#endif
        if(obj==null){Debug.LogError("No playable character found in scene/build.");return;}var root=new GameObject("Lumberjack Player");obj.transform.SetParent(root.transform,true);obj.transform.position=Vector3.zero;obj.transform.rotation=Quaternion.identity;animator=obj.GetComponentInChildren<Animator>();if(animator!=null){animator.applyRootMotion=false;animator.cullingMode=AnimatorCullingMode.AlwaysAnimate;normalController=animator.runtimeAnimatorController;animator.Rebind();FreezeStandingPose();}GroundVisual(obj,.05f);player=root.transform;MakeAxe();}
    void MakeAxe(){var pivot=new GameObject("Axe Pivot");pivot.transform.SetParent(player);pivot.transform.localPosition=new Vector3(.48f,1.25f,.48f);axePivot=pivot.transform;var handle=GameObject.CreatePrimitive(PrimitiveType.Cylinder);handle.transform.SetParent(axePivot);handle.transform.localPosition=new Vector3(0,.42f,0);handle.transform.localScale=new Vector3(.055f,.48f,.055f);Paint(handle,new Color(.38f,.19f,.07f));Destroy(handle.GetComponent<Collider>());var head=GameObject.CreatePrimitive(PrimitiveType.Cube);head.transform.SetParent(axePivot);head.transform.localPosition=new Vector3(.12f,.88f,0);head.transform.localScale=new Vector3(.34f,.18f,.12f);Paint(head,new Color(.35f,.38f,.4f));Destroy(head.GetComponent<Collider>());pivot.SetActive(false);}
    void GroundVisual(GameObject visual,float y){if(animator!=null)animator.Update(0);float minY=float.PositiveInfinity;foreach(var r in visual.GetComponentsInChildren<Renderer>()){if(r is SkinnedMeshRenderer s)s.updateWhenOffscreen=true;minY=Mathf.Min(minY,r.bounds.min.y);}if(float.IsFinite(minY))visual.transform.position+=Vector3.up*(y-minY);}
    Material Mat(Color c){Shader s=Shader.Find("Universal Render Pipeline/Lit");if(s==null)s=Shader.Find("Sprites/Default");var m=new Material(s);m.color=c;return m;}void Paint(GameObject o,Color c){var r=o.GetComponent<Renderer>();if(r!=null)r.material=Mat(c);}
    void MakeGround(){var g=GameObject.CreatePrimitive(PrimitiveType.Plane);g.transform.localScale=new Vector3(3.2f,1,3.2f);Paint(g,new Color(.36f,.64f,.25f));}void MakeLight(){var o=new GameObject("Warm Sun");var l=o.AddComponent<Light>();l.type=LightType.Directional;l.intensity=1.25f;l.color=new Color(1,.91f,.76f);o.transform.rotation=Quaternion.Euler(48,-35,0);}void MakeCamera(){var o=new GameObject("Main Camera");o.tag="MainCamera";cam=o.AddComponent<Camera>();cam.orthographic=true;cam.orthographicSize=7.5f;o.transform.position=new Vector3(9.5f,11,-9.5f);o.transform.rotation=Quaternion.Euler(38,-42,0);cam.backgroundColor=new Color(.65f,.82f,.92f);}
    void MakeForest(){Vector3[] p={new(-7,0,-5),new(-5,0,-7),new(-3,0,-6),new(5,0,-6),new(7,0,-3),new(-7,0,2),new(-6,0,6),new(5,0,6),new(7,0,4),new(3,0,7)};foreach(var v in p)Tree(v);}void Tree(Vector3 p){var r=new GameObject("Tree");r.transform.position=p;r.AddComponent<TreeNode>();var t=GameObject.CreatePrimitive(PrimitiveType.Cylinder);t.transform.SetParent(r.transform);t.transform.localPosition=new Vector3(0,1.4f,0);t.transform.localScale=new Vector3(.42f,1.4f,.42f);Paint(t,new Color(.42f,.23f,.1f));for(int i=0;i<3;i++){var f=GameObject.CreatePrimitive(PrimitiveType.Sphere);f.transform.SetParent(r.transform);f.transform.localPosition=new Vector3((i-1)*.55f,3.1f+(i%2)*.35f,0);f.transform.localScale=new Vector3(1.5f,1.25f,1.5f);Paint(f,new Color(.12f,.48f,.16f));}}
    void MakeSawmill(){var root=new GameObject("Sawmill");root.transform.position=new Vector3(4,0,1);sawmill=root.transform;var table=GameObject.CreatePrimitive(PrimitiveType.Cube);table.transform.SetParent(root.transform);table.transform.localPosition=new Vector3(0,.65f,0);table.transform.localScale=new Vector3(4,.35f,1.7f);Paint(table,new Color(.38f,.23f,.12f));var blade=GameObject.CreatePrimitive(PrimitiveType.Cylinder);blade.transform.SetParent(root.transform);blade.transform.localPosition=new Vector3(0,1.45f,0);blade.transform.localScale=new Vector3(1.25f,.12f,1.25f);blade.transform.rotation=Quaternion.Euler(90,0,0);Paint(blade,Color.gray);}
}